# -*- coding: utf-8 -*-
# Каркас презентации без заглушек + annotations.md (полный текст доклада).
#   python build3.py out.pptx [annotations.md]
# Раскладка — по 07-storyboard-final (A сверху / B снизу / колонка шапок + мини-карта), текст речи — из 06-talk-final.md,
# числа — только Docker node:24.21.0-alpine (issues-memory-research/v8-experiment/docker/out/alpine-node24/NUMBERS.md).
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__))
_b2 = open(os.path.join(HERE, 'build2.py'), encoding='utf-8').read().split('\n# ================= СЛАЙДЫ')[0]
exec(_b2)
exec(open(os.path.join(HERE, 'lib3.py'), encoding='utf-8').read())

ANN_OUT = sys.argv[2] if len(sys.argv) > 2 else os.path.join(os.path.dirname(HERE), 'annotations.md')
ANN = []          # записи для annotations.md в порядке слайдов
REPO = 'https://github.com/Yoshimuro/issues-memory-research/tree/v8-talk-verify'


def column(s, sid):
    st = ab_pairs(sid) or {}
    for i, (k, node) in enumerate(SLOTS):
        y = Y0 + i * 0.8
        a, b = st.get(k, ('—', '—')); filled = a != '—' or b != '—'
        if filled: clone(s, 'white', RX, y, RW, 0.72)
        else: rect(s, RX, y, RW, 0.72, 'F3F4F6', line='D9DDE3', radius=0.14, dash=True)
        text(s, RX + 0.15, y + 0.06, RW - 0.3, 0.2, k, size=9, color=MUTED)
        text(s, RX + 0.15, y + 0.06, RW - 0.3, 0.2, f'узел {node}', size=9, color=MUTED, align='r')
        long = len(a) + len(b) > 22
        ctext(s, RX + 0.1, y + 0.26, RW - 0.2, 0.42, [(a, GREEN if filled else 'B6BCC6'), ('  /  ', 'B6BCC6'), (b, BRED if filled else 'B6BCC6')], size=9 if long else 15)
    minimap(s, RX, Y0 + 4.0, RW, Y1 - (Y0 + 4.0), int(sid.split('.')[0]))


def ann(sid, title, mins, screen, speech, demo=None, kind='слайд'):
    ANN.append(dict(sid=sid, title=title, mins=mins, screen=screen, speech=speech, demo=demo, kind=kind))


def finish(s, sid, screen, demo=None, title=None):
    d = SL[sid]
    s.notes_slide.notes_text_frame.text = f'[{sid} · {d["mins"]} мин]\n\n{d["Речь"]}' + (f'\n\n— — —\nДЕМО: {demo}' if demo else '')
    ann(sid, title or d['title'], d['mins'], screen, d['Речь'], demo)


def light(sid, bg='green', title=None):
    s = prs.slides.add_slide(LAY[bg])
    set_title(s, title or SL[sid]['title'])
    tt = s.shapes.title
    tt.left, tt.top, tt.width, tt.height = Inches(0.37), Inches(0.40), Inches(11.0), Inches(0.58)
    drop_empty_placeholders(s)
    text(s, 11.4, 0.42, 1.55, 0.3, sid, size=11, color=MUTED, align='r')
    column(s, sid)
    return s


def divider(n):
    nd = NODES[n]; q = NODES[n - 1]['q']
    dark(f'Узел {n} из 12 · {nd["mins"]} мин', nd['title'], ['Вопрос зала:', q], note=f'Разделитель узла {n}.\n\n{q}', big_size=40)
    ann(f'узел {n}', nd['title'], nd['mins'], f'Тёмный слайд-разделитель: «Узел {n} из 12», название узла и вопрос, на который он отвечает.',
        f'Итак, вопрос. {q} (Разделитель: вопрос, которым закончился прошлый узел, звучит ещё раз — дальше узел на него отвечает. Пауза в пару секунд, пока зал читает слайд.)', kind='разделитель')


def breather(n, k):
    s = prs.slides.add_slide(LAY['white'])
    set_title(s, f'Где мы · после узла {n}')
    drop_empty_placeholders(s)
    talk_map(s, 0.47, 1.7, 12.38, 5.0, upto=n, current=n)
    said = {1: 'Два шага движка позади: форма и место чтения. Впереди — компилятор и сервер.',
            2: 'Движок пройден от файла до ставки. Дальше — сервер, а потом тот, кто написал текст.',
            3: 'Путь по вызовам закрыт числом на сервере, а назад, к автору текста, мы дошли до корпуса. Осталось: правила, лев и карта целиком.'}[k]
    s.notes_slide.notes_text_frame.text = 'ПЕРЕДЫШКА, 5 секунд. ' + said
    ann(f'передышка {k}', f'Где мы · после узла {n}', '0.1', f'Карта доклада целиком: шаги 1–{n} проявлены (у каждого — что у A, что у B и чем это увидеть), остальные приглушены.',
        f'Пауза на пять секунд, одна фраза: «{said}» Дать залу посмотреть на карту и выдохнуть.', kind='передышка')


